var n=`1183-guacamole`;var a=`world-1183`;var o=`MX`;var t=`central-america-caribbean`;var s=4;var r=21;var d={en:`Guacamole`,ua:`Гуакамоле`};var c={en:`Guacamole is a dish from Mexico prepared with avocado, tomato, red onion, serrano pepper. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Гуакамоле, страва кухні країни Мексика, яку готують із таких продуктів: авокадо, помідор, червона цибуля, перець серрано. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Drain the cooked ingredients and pound or mash while warm for about 6 minutes until thick, elastic and smooth; shape into portions with wet hands or a spoon.`,ua:`Злийте воду з готових продуктів і протягом приблизно 6 хвилин товчіть або розминайте теплими до густої гладкої еластичної маси; сформуйте порції вологими руками чи ложкою.`,t:[`mashing`,`pounding`],m:6,i:[[`avocado`,4,`pcs`]]},{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:8,i:[[`tomato`,180,`g`],[`red-onion`,125,`g`],[`serrano-pepper`,1,`pcs`],[`cilantro`,25,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`lime-juice`,55,`ml`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`ground-cumin`,2,`g`]]}];var m={slug:n,id:a,country:`MX`,region:t,servings:4,minutes:21,title:d,text:c,steps:l};export{o as country,m as default,a as id,r as minutes,t as region,s as servings,n as slug,l as steps,c as text,d as title};